#!/usr/bin/env python3
"""Verify an AI-first documentation set generated by init-ai-first-project.

Usage:
    python scripts/verify_docs.py [--root PATH] [--strict]

The script checks the machine-checkable rules in references/doc-model.md:
required files, AGENTS.md budget, spec sections and command verification,
plan-map IDs/states/paths, status consistency, tickets.md/tickets/ sync,
markdown links, template placeholders, and gitignore state.

Exit code 0 = no errors (warnings allowed); 1 = at least one error.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path
from urllib.parse import unquote

if hasattr(sys.stdout, "reconfigure"):
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except OSError:
        pass

FEATURE_STATES = {"proposed", "planned", "in-progress", "verifying", "accepted"}
TICKET_STATES = {"blocked", "ready-for-agent", "in-progress", "verifying", "accepted"}
SPEC_SECTIONS = {1, 2, 3, 4, 5, 6, 7, 8, 10, 11, 12}  # 9 is optional
OPTIONAL_SPEC_SECTIONS = {9}

REQUIRED_FILES = [
    "AGENTS.md",
    "docs/spec.md",
    "docs/plan-map.md",
    "docs/status.md",
    "docs/README.md",
    "docs/features/README.md",
    "docs/issue-tracker.md",
    "docs/adr/README.md",
    "docs/templates/plan.md",
    "docs/templates/tickets.md",
    "docs/templates/acceptance.md",
    "docs/templates/adr.md",
]

PLACEHOLDER_PATTERNS = [
    (re.compile(r"\[ \]"), "[ ] 占位符"),
    (re.compile(r"YYYY-MM-DD"), "YYYY-MM-DD 占位符"),
    (re.compile(r"\[项目名\]"), "[项目名] 占位符"),
]


class Report:
    def __init__(self) -> None:
        self.errors: list[str] = []
        self.warnings: list[str] = []

    def error(self, path: Path | str, message: str) -> None:
        self.errors.append(f"{path}: {message}")

    def warn(self, path: Path | str, message: str) -> None:
        self.warnings.append(f"{path}: {message}")

    def print(self) -> None:
        for item in self.errors:
            print(f"[ERROR] {item}")
        for item in self.warnings:
            print(f"[WARN]  {item}")
        print(f"\n{len(self.errors)} error(s), {len(self.warnings)} warning(s)")
        if self.errors:
            print("FAILED")
        else:
            print("PASSED")


def read_text(path: Path, report: Report) -> str:
    if not path.exists():
        report.error(path, "文件不存在")
        return ""
    try:
        return path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        report.error(path, "不是 UTF-8 文本")
        return ""


def section(text: str, number: int) -> str | None:
    match = re.search(rf"(?m)^##\s+{number}\.\s+.*$", text)
    if not match:
        return None
    rest = text[match.end():]
    nxt = re.search(r"(?m)^##\s+\d+\.", rest)
    return rest[: nxt.start()] if nxt else rest


def table_blocks(text: str) -> list[list[list[str]]]:
    """Return contiguous markdown tables as lists of rows of cells."""
    blocks: list[list[list[str]]] = []
    current: list[str] = []
    for line in text.splitlines() + [""]:
        stripped = line.strip()
        if stripped.startswith("|") and stripped.endswith("|"):
            current.append(stripped)
            continue
        if current:
            rows: list[list[str]] = []
            for raw in current:
                cells = [cell.strip() for cell in raw.strip("|").split("|")]
                if all(set(cell) <= set("-: ") for cell in cells):
                    continue
                rows.append(cells)
            if rows:
                blocks.append(rows)
            current = []
    return blocks


def find_table(text: str, *header_words: str) -> list[list[str]] | None:
    for block in table_blocks(text):
        header = block[0]
        joined = " ".join(header)
        if all(word in joined for word in header_words):
            return block[1:]
    return None


def strip_code(text: str) -> str:
    text = re.sub(r"```.*?```", "", text, flags=re.S)
    return re.sub(r"`[^`\n]*`", "", text)


def check_required_files(root: Path, report: Report) -> None:
    for rel in REQUIRED_FILES:
        if not (root / rel).is_file():
            report.error(rel, "必需文件不存在")


def check_agents(root: Path, report: Report) -> None:
    path = root / "AGENTS.md"
    text = read_text(path, report)
    if not text:
        return
    lines = len(text.splitlines())
    if lines > 150:
        report.error(path, f"{lines} 行，超过硬上限 150 行")
    elif lines > 80:
        report.warn(path, f"{lines} 行，超过建议的 40–80 行")
    for required in (
        "docs/spec.md",
        "docs/status.md",
        "docs/plan-map.md",
        "docs/features/README.md",
        "docs/issue-tracker.md",
        "docs/adr/",
        "docs/README.md",
        "docs/templates/",
    ):
        if required not in text:
            report.error(path, f"文件索引缺少 {required}")
    if "## 会话开始" not in text:
        report.warn(path, "缺少“会话开始”例程")
    if "[项目名]" in text:
        report.error(path, "项目名占位符未替换")


def check_spec(root: Path, report: Report) -> None:
    path = root / "docs/spec.md"
    text = read_text(path, report)
    if not text:
        return
    for number in sorted(SPEC_SECTIONS):
        if section(text, number) is None:
            report.error(path, f"缺少第 {number} 章")
    for number in sorted(OPTIONAL_SPEC_SECTIONS):
        body = section(text, number)
        if body is None:
            report.warn(path, f"可选的第 {number} 章不存在")
        elif not body.strip():
            report.warn(path, f"可选的第 {number} 章为空，应写 N/A 并说明")

    commands = section(text, 5)
    if commands is None:
        return
    rows = find_table(commands, "验证状态")
    if rows is None:
        report.error(path, "§5 缺少带“验证状态”列的 Commands 表")
        return
    for row in rows:
        if len(row) < 5 or not row[0] or row[0] in {"用途", "---"}:
            continue
        status = row[-1].strip().strip("`").strip()
        command = row[1].strip("` ")
        if command == "TBD":
            report.warn(path, f"命令仍为 TBD：{row[0]}")
            continue
        if command in {"", "[ ]", "-"}:
            report.error(path, f"命令行为空：{row[0]}")
        if not re.match(r"^(Verified:|Unverified:|N/A)", status):
            report.error(path, f"命令“{row[0]}”没有验证状态（当前：{status or '空'}）")


def check_plan_map(root: Path, report: Report) -> dict[str, str]:
    path = root / "docs/plan-map.md"
    text = read_text(path, report)
    if not text:
        return {}
    ids: dict[str, str] = {}

    queue = find_table(text, "ID", "状态", "文档目录")
    if queue is None:
        report.error(path, "缺少演进队列表（ID/状态/文档目录）")
        return ids
    for row in queue:
        if len(row) < 7 or not re.fullmatch(r"F-\d{3}", row[0]):
            continue
        feature_id, name, state, directory = row[0], row[1], row[2], row[5]
        if feature_id in ids:
            report.error(path, f"{feature_id} 重复")
        if state not in FEATURE_STATES:
            report.error(path, f"{feature_id} 状态非法：{state}")
        if not name:
            report.error(path, f"{feature_id} 缺少名称")
        ids[feature_id] = state
        directory = directory.strip("` ")
        if directory and directory not in {"-", "—"}:
            if "F-NNN" not in directory and not (root / directory).is_dir():
                report.error(path, f"{feature_id} 文档目录不存在：{directory}")

    archive = find_table(text, "ID", "完成日期", "提交")
    if archive is not None:
        for row in archive:
            if len(row) < 6 or not re.fullmatch(r"F-\d{3}", row[0]):
                continue
            if row[5].strip("` ") in {"", "-", "[ ]"}:
                report.error(path, f"归档 {row[0]} 缺少提交")
    return ids


def check_status(root: Path, report: Report, plan_ids: dict[str, str]) -> None:
    path = root / "docs/status.md"
    text = read_text(path, report)
    if not text:
        return
    fields: dict[str, str] = {}
    for match in re.finditer(r"(?m)^-\s*([A-Za-z][A-Za-z ]+):\s*(.*)$", text):
        fields[match.group(1).strip()] = match.group(2).strip()
    for key in ("Updated", "Active", "Next", "Blockers", "Last verification", "Last commit"):
        if not fields.get(key):
            report.error(path, f"缺少字段或值为空：{key}")
    if fields.get("Updated") and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", fields["Updated"]):
        report.error(path, f"Updated 不是日期：{fields['Updated']}")

    active = fields.get("Active", "")
    if active != "Idle":
        match = re.search(r"(F-\d{3})", active)
        if not match:
            report.error(path, f"Active 不是 Idle 或 F-NNN：{active}")
        else:
            feature_id = match.group(1)
            if feature_id not in plan_ids:
                report.error(path, f"Active 的 {feature_id} 不在 plan-map 中")
            else:
                state_match = re.search(r"[-—]\s*([a-z-]+)\s*$", active)
                if state_match and state_match.group(1) != plan_ids[feature_id]:
                    report.error(
                        path,
                        f"Active 阶段 {state_match.group(1)} 与 plan-map 的 {plan_ids[feature_id]} 不一致",
                    )
    elif any(state in {"in-progress", "verifying"} for state in plan_ids.values()):
        report.error(path, "有进行中的 feature，但 Active 是 Idle")


def check_features(root: Path, report: Report, plan_ids: dict[str, str]) -> None:
    features_dir = root / "docs/features"
    if not features_dir.is_dir():
        return
    for feature_dir in sorted(p for p in features_dir.iterdir() if p.is_dir()):
        if not re.fullmatch(r"F-\d{3}-[a-z0-9-]+", feature_dir.name):
            continue
        feature_id = feature_dir.name[:5]
        state = plan_ids.get(feature_id)
        if not (feature_dir / "plan.md").is_file():
            report.error(feature_dir, "缺少 plan.md")
        tickets_path = feature_dir / "tickets.md"
        if state in {"in-progress", "verifying", "accepted"} and not tickets_path.is_file():
            report.error(feature_dir, f"状态 {state} 但缺少 tickets.md")
        if tickets_path.is_file():
            check_ticket_map(tickets_path, feature_dir, report)

    archive = root / "docs/archive/features"
    if archive.is_dir():
        for archived in sorted(p for p in archive.iterdir() if p.is_dir()):
            if not re.fullmatch(r"F-\d{3}-[a-z0-9-]+", archived.name):
                continue
            if not (archived / "acceptance.md").is_file():
                report.error(archived, "归档 feature 缺少 acceptance.md")


def check_ticket_map(path: Path, feature_dir: Path, report: Report) -> None:
    text = read_text(path, report)
    if not text:
        return
    rows = find_table(text, "工单", "状态", "文件")
    if rows is None:
        report.error(path, "缺少工单地图表（工单/状态/文件）")
        return
    seen = 0
    for row in rows:
        if len(row) < 7 or not re.fullmatch(r"\d{2}", row[0]):
            continue
        seen += 1
        ticket_id, status, link_cell = row[0], row[2], row[-1]
        if status not in TICKET_STATES:
            report.error(path, f"工单 {ticket_id} 状态非法：{status}")
        match = re.search(r"\[[^\]]+\]\(([^)]+)\)", link_cell)
        if not match:
            report.error(path, f"工单 {ticket_id} 缺少文件链接")
            continue
        target = unquote(match.group(1).split("#", 1)[0])
        ticket_path = (feature_dir / target).resolve()
        if not ticket_path.is_file():
            report.error(path, f"工单 {ticket_id} 链接不存在：{target}")
            continue
        ticket_text = read_text(ticket_path, report)
        status_match = re.search(r"(?m)^\*\*Status:\*\*\s*(\S+)", ticket_text)
        if not status_match:
            report.error(ticket_path, "缺少 **Status:**")
        elif status_match.group(1) != status:
            report.error(
                ticket_path,
                f"Status {status_match.group(1)} 与 tickets.md 的 {status} 不一致",
            )
        if "**Blocked by:**" not in ticket_text:
            report.error(ticket_path, "缺少 **Blocked by:**")
        if not re.search(r"(?m)^-\s*\[[ xX]\]", ticket_text):
            report.warn(ticket_path, "没有验收标准 checklist")
    if seen == 0 and "暂无" not in text:
        report.error(path, "工单地图没有任何工单")


def check_issue_tracker(root: Path, report: Report) -> None:
    path = root / "docs/issue-tracker.md"
    text = read_text(path, report)
    if not text:
        return
    if "tickets/" not in text:
        report.error(path, "没有指向 tickets/ 工单目录")
    for state in TICKET_STATES:
        if state not in text:
            report.error(path, f"状态值缺失：{state}")


def check_links(root: Path, report: Report) -> None:
    candidates = [root / "AGENTS.md"]
    docs = root / "docs"
    if docs.is_dir():
        candidates.extend(sorted(docs.rglob("*.md")))
    for path in candidates:
        if not path.is_file() or "templates" in path.parts:
            continue
        text = strip_code(read_text(path, report))
        for match in re.finditer(r"\[[^\]]+\]\(([^)]+)\)", text):
            target = match.group(1).strip()
            if re.match(r"^(https?://|mailto:|#)", target):
                continue
            if any(token in target for token in ("<", ">", "{", "}", "*", "F-NNN", "NN-")):
                continue
            target = unquote(target.split("#", 1)[0].split("?", 1)[0])
            if not target:
                continue
            resolved = (path.parent / target).resolve()
            if not resolved.exists():
                report.error(path, f"链接不存在：{target}")


def check_placeholders(root: Path, report: Report) -> None:
    for rel in REQUIRED_FILES:
        path = root / rel
        if not path.is_file() or "templates" in path.parts:
            continue
        text = read_text(path, report)
        for pattern, label in PLACEHOLDER_PATTERNS:
            if pattern.search(text):
                report.warn(path, f"仍有{label}")
    features = root / "docs/features"
    if features.is_dir():
        for path in sorted(features.rglob("*.md")):
            if path.name == "README.md" or "templates" in path.parts:
                continue
            text = read_text(path, report)
            for pattern, label in PLACEHOLDER_PATTERNS:
                if pattern.search(text):
                    report.warn(path, f"仍有{label}")


def check_gitignore(root: Path, report: Report) -> None:
    try:
        inside = subprocess.run(
            ["git", "-C", str(root), "rev-parse", "--is-inside-work-tree"],
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        report.warn("git", "未安装 git，跳过 .gitignore 检查")
        return
    if inside.returncode != 0 or inside.stdout.strip() != "true":
        report.warn(root, "不在 git 仓库中，跳过 .gitignore 检查")
        return
    features = root / "docs/features"
    if not features.is_dir():
        return
    for tickets_dir in sorted(p for p in features.glob("F-*/tickets") if p.is_dir()):
        relative = tickets_dir.relative_to(root).as_posix()
        ignored = subprocess.run(
            ["git", "-C", str(root), "check-ignore", "-q", relative],
            capture_output=True,
            text=True,
            check=False,
        )
        if ignored.returncode == 0:
            report.error(tickets_dir, "被 .gitignore 忽略，工单不会随 feature 提交")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", default=".", help="项目根目录（默认当前目录）")
    parser.add_argument(
        "--strict",
        action="store_true",
        help="把 warning 当作 error（CI 使用）",
    )
    args = parser.parse_args()
    root = Path(args.root).resolve()
    report = Report()

    if not root.is_dir():
        print(f"ERROR: 根目录不存在：{root}")
        return 1

    check_required_files(root, report)
    check_agents(root, report)
    check_spec(root, report)
    plan_ids = check_plan_map(root, report)
    check_status(root, report, plan_ids)
    check_features(root, report, plan_ids)
    check_issue_tracker(root, report)
    check_links(root, report)
    check_placeholders(root, report)
    check_gitignore(root, report)

    report.print()
    if report.errors or (args.strict and report.warnings):
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
